// TH14 v1.00b Stage 3 mid-stage wave.
// Entry st03.ecl.txt:711-716 (MainSub06) creates GirlD01 x3 at local 0/120/240.
// Dependency: GirlD01 295-317 (per-enemy setup/move) and GirlD01_at 319-374 (attack).
// Source frame 0 == card frame OPENING_BUFFER. Ranks 0..3 = source !E/!N/!H/!LO(L).

const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;
const GIRL_HP: int = 1200;

// GirlD01_at: one volley per loop step; both fan bullets of a step share that step's
// EX record, so the two %RANDRAD draws at 356-357 are sampled once per volley.
async sub girl_attack() {
    wait(60);                                              // 322
    var rank: int = global(GVAR_RANK);
    var volleys: int = 2;                                  // diffI($B,2,4,6,8) 336
    var interval: int = 40;                                // wait([-1]) 361-370
    var layers: int = 2;                                   // pushed int 347-354 -> SHOOT d
    var speed0: fx = 2.0fx;                                // pushed float 339-346 -> SHOOT m
    if rank == RANK_NORMAL { volleys = 4; interval = 20; } // !N
    if rank >= RANK_HARD { volleys = 6; interval = 13; layers = 3; speed0 = 2.5fx; } // !H
    if rank >= RANK_LUNATIC { volleys = 8; interval = 10; speed0 = 3.0fx; }          // !LO
    var spread: angle = 90deg;                             // %A = 1.570796f 335
    for k in 0..volleys {
        var r: angle = (rand(65536) - 32768) as angle;      // RANDRAD = -pi..pi 356
        var s: angle = (rand(65536) - 32768) as angle;      // RANDRAD 357
        // etAim(0,1)+etCount(0,2,1)+etAngle(0,1.5707964,%A) 324/326/358: fixed fan, two
        // lanes at +-spread/2 (source creates the +side lane first).
        var half: angle = (((spread as int) / 2) as angle);
        var a0: angle = 90deg + half;
        var a1: angle = 90deg - half;
        // etSprite(0,19,3) 325, etSpeed(0,0.2,0.2) 328; EX 329-334 keeps WAIT 120 before SHOOT
        // (ANIM/BRIGHT/SPEEDUP are birth presentation, omitted by policy).
        _ = fire(TH14_BIG_BALL2, 3, $self_x, $self_y, 0.2fx, a0, PARENT_DIE, none);
        _ = fire(TH14_BIG_BALL2, 3, $self_x, $self_y, 0.2fx, a1, PARENT_DIE, none);
        // SHOOT 333 fires from each parent's position after the 120-frame wait;
        // SHOOT_DATA 334 (sprite 5, color 6, c=1) deletes the parent right then.
        spawn split($self_x + 24fx * cos(a0), $self_y + 24fx * sin(a0), r, s, layers, speed0);
        spawn split($self_x + 24fx * cos(a1), $self_y + 24fx * sin(a1), r, s, layers, speed0);
        spread = spread - 15deg;                           // %A -= 0.261799f 360
        wait(interval);
    }
}

// SHOOT 333: aim mode 3 (fixed-direction ring), 8 lanes, `layers` speed steps
// speed0..0.9, base/layer rotation = the volley's two RANDRAD values.
// Children inherit EX from index 8 (ANIM/PLAYSOUND only, omitted).
async sub split(cx: fx, cy: fx, base: angle, step: angle, layers: int, speed0: fx) {
    wait(119);                                             // parent EX WAIT 120 (332), task starts +1
    sh_reset(0);
    sh_sprite(0, TH14_BALL2, 6);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 8, layers);
    sh_speed(0, speed0, (0.9fx - speed0) / ((layers - 1) as fx));
    sh_angle(0, base, step);
    sh_offset_abs(0, cx, cy);
    sh_fire(0);
}

// Parent EX: WAIT 120 then the split's SHOOT_DATA deletes the parent bullet.
xformdef PARENT_DIE {
    wait(120);
    set_life(1);
}

// st03.ecl.txt:295-317. Boxes 303/304 (32x32 hurt, 24x24 body -> half radius),
// moveVel 305 (pi/2, 2.7) + moveSpeedTime 306/309 (mode 1 = t^2).
async sub girl() {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 2.7fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_QUAD_IN);
    spawn girl_attack();                                   // @GirlD01_at() async 307
    wait(120);                                             // 308
    move_speed(80, 1fx, EASE_QUAD_IN);                     // 309
    wait(60);                                              // 310
    loop { wait(1000); }                                   // 313-315 endless wait loop
}

// st03.ecl.txt:711-716 schedule: create at local 0/120/240, trailing wait 120.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -48fx, GIRL_HP, 0, 0, 0, girl);
    wait(120);
    _ = spawn_enemy(64fx, -48fx, GIRL_HP, 0, 0, 0, girl);
    wait(120);
    _ = spawn_enemy(-64fx, -48fx, GIRL_HP, 0, 0, 0, girl);
    wait(120);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
